INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'limpopo-festive-season-police-launch-67-vehicles-2026-10-22',
  'Limpopo launches festive season policing with 67 new vehicles',
  'Community', '2026-10-22', 'Review (Caxton Local Media)', 'https://www.citizen.co.za/review-online/news-headlines/local-news/2026/10/22/safer-festive-season-operations-launched-in-limpopo-with-67-vehicles/',
  'Limpopo''s Safer Festive Season Operations were launched on 22 October at Thavhani Mall in Thohoyandou, with 67 law enforcement vehicles handed to police.',
  'The provincial Safer Festive Season Operations were officially launched on Thursday, 22 October at Thavhani Mall in Thohoyandou. The Limpopo provincial police commissioner handed over 67 law enforcement vehicles at the event, which the Limpopo Chronicle reports is meant to raise police visibility, widen operational capacity and speed up response times.

The Transport and Community Safety MEC attended the launch together with local leaders. According to the Limpopo Chronicle, the aim is to strengthen cooperation between police and community structures and to encourage residents to take part in crime prevention. A briefing on safety concerns in the Thohoyandou policing area and across the province followed.

Review reports that the MEC pointed to reckless driving, speeding, drunk drivers and vehicles that are not roadworthy as the main road safety worries, and named the N1, R81, R524 and R71 as routes of concern. Motorists in the Polokwane area who travel on these roads over the holiday period should expect continued enforcement attention.

Review also reports that the MEC urged residents to use 10111 or the MySAPS app when reporting crime, and asked communities to speak out against gender-based violence, particularly where alcohol abuse is involved.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/review-online/news-headlines/local-news/2026/10/22/safer-festive-season-operations-launched-in-limpopo-with-67-vehicles/", "https://www.limpopochronicle.co.za/2026/10/22/limpopo-provincial-commissioner-hands-over-67-new-police-vehicles/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'limpopo-investment-conference-polokwane-informal-traders-2026-10-21',
  'Polokwane small traders ask for a share of Limpopo investment pledges',
  'Business', '2026-10-21', 'Review (Caxton Local Media)', 'https://www.citizen.co.za/review-online/news-headlines/local-news/2026/10/21/polokwane-informal-traders-want-a-slice-of-the-investment-pledges-cake/',
  'After the sixth Limpopo Investment Conference at The Ranch Resort in Polokwane, informal traders say local small businesses must also benefit from the pledges.',
  'The sixth Limpopo Investment Conference took place on 15 October at The Ranch Resort in Polokwane. Government says more than R452 billion in investment pledges has been secured since 2021, with over R71 billion already implemented, according to the Deputy President''s keynote address published on gov.za.

Review reports that informal traders and small business owners in Polokwane want a share of the opportunities. A senior office-bearer of a provincial association for small and informal businesses attended to build networks and held talks with network connectivity companies, the Limpopo Tourism Agency and the Chinese ambassador. He explained that the bulk of that membership trades informally, with tuck shop operators making up the next largest group.

In his address the Deputy President said the InvestSA One Stop Shop, which lets investors deal with government services through one office, has been launched in Limpopo. He also said nearly 24,000 jobs have been created.

Review adds that the DA in Limpopo argues pledges mean little without reliable water, electricity and roads, and wants the conference judged by how many projects actually get delivered and how many jobs result.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/review-online/news-headlines/local-news/2026/10/21/polokwane-informal-traders-want-a-slice-of-the-investment-pledges-cake/", "https://www.gov.za/news/speeches/deputy-president-paul-mashatile-limpopo-investment-conference-2026-15-oct-2026"]',
  'agent'
);
